  if (current) {
    saveResult = updateContact(currentId, model);
  } else {
    saveResult = V8.MongoDb.AddFormData({
      OsClient: V8.OsClient, DbName: DB_NAME, TableName: CONTACT_TABLE,
      Id: deterministicId, _FormData: model
